target = "....((((..(((((..((((..((((.....))))((((((...))).)))))))((((((.((.((.(((((....)).)))))))(((((.((.((.((....))))))(((((.(((....)).))).)))..)).)))))).))))))))(((.(((.(((.((((....))))))))))((((((((...))).)).))).)))))))"
N=len(target)
seq=['A']*N

units = {
    (23,35): "GGUGUUGUUCAUC",
    (36,51): "GGAGCUGUAGGCAUCU",
    (63,87): "GCACUCACGUUAAAGGACCGUAGGC",
    (94,111): "GCAUGUGUAGAGGCCAGC",
    (112,134): "GGCCGUCCGUUCUCGAGUGUGCU",
    (159,184): "GAGCGGGUCGAUCAGCGUCGCCUCUU",
    (185,205): "CUCUAGCCACGGGCGUACGAG",
}
for (a,b),s in units.items():
    for k,ch in enumerate(s):
        seq[a+k]=ch

# junction closing pairs: put G-C
juncs = [(7,210),(14,150),(20,52),(61,143),(92,137),(157,207)]
for i,j in juncs:
    if seq[i]=='A': seq[i]='G'
    if seq[j]=='A': seq[j]='C'

# Now for any '(' or ')' position still 'A' (not in a unit, not a junction), assign complementary pairs.
# We need to assign pairs. Walk pairs via stack.
stack=[]
pairs={}
for i,ch in enumerate(target):
    if ch=='(':
        stack.append(i)
    elif ch==')':
        j=stack.pop()
        pairs[(j,i)]=None

# For unassigned paired positions, assign G-C (strong). Left='(', right=')'
for (i,j) in pairs:
    if seq[i]=='A' and seq[j]=='A':
        seq[i]='G'; seq[j]='C'
    elif seq[i]=='A':
        # match partner
        comp={'G':'C','C':'G','A':'U','U':'A'}
        seq[i]=comp[seq[j]]
    elif seq[j]=='A':
        comp={'G':'C','C':'G','A':'U','U':'A'}
        seq[j]=comp[seq[i]]

# unpaired '.' positions remain 'A' (A-rich linkers). But check triloop caps recommended. Leave A for now.
seq=''.join(seq)
print(seq)
print(len(seq))
EOF

